    def chat_event(self, chat: Chat, message: str = None, event_type: str = None) -> None:
        """
        Emit a chat event through the session's event manager.

        ADDED: ``ChatEngine`` is not the only producer of chat events — the API
        routers (``POST /api/chats``, ``POST /api/chats/from-url``) and the
        Socket.IO handlers announce progress *before* starting a turn. They call
        ``session.chat_event(...)``, a method that did not exist: the resulting
        ``AttributeError`` was swallowed by the endpoint and the response was an
        error object instead of the processed chat.

        Args:
            chat: The chat the event refers to.
            message: Human readable progress message.
            event_type: Optional event type (``changed``, ``created``, ``error``...).
        """
        self.event_manager.chat_event(
            chat=chat, message=message, event_type=event_type
        )

    def coder_open_file(self, file_name: str) -> dict:
        """Open a file in the code server editor."""
        if not os.path.isfile(file_name) and not file_name.startswith(
            self.settings.abs_project_path
        ):
            file_name = f"{self.settings.abs_project_path}/{file_name}".replace("//", "/")

        cmd = f'code-server -r "{file_name}"'
        os.system(cmd)
        return {
            "cmd": cmd,
            "project_path": self.settings.abs_project_path,
            "file_name": file_name,
        }

    @contextmanager
    def chat_action(self, chat: Chat, event: str):
        """Context manager for wrapping chat actions with event notifications."""
        self.event_manager.chat_event(chat=chat, message=f"{event} starting")
        self.log_info(f"Start chat {chat.name}")
        try:
            yield
        except Exception as ex:
            self.event_manager.chat_event(
                chat=chat, message=f"{event} error: {ex}", event_type="error"
            )
            self.log_exception(f"Chat {chat.name} {event} error: {ex}")
        finally:
            self.event_manager.chat_event(chat=chat, message=f"{event} done")
            self.log_info(f"Chat done {chat.name}")

    def delete_project(self) -> None:
        """Delete the project directory."""
        project_id = self.settings.project_id
        project_name = self.settings.project_name
        codx_path = self.settings.codx_path
        shutil.rmtree(codx_path)
        logger.error("PROJECT REMOVED %s", codx_path)

        # The project is gone: every client must drop it from its cached list
        # (and leave the screen when it was the active one). Best effort: the
        # folder is already removed.
        emit_collection_event(
            COLLECTION_PROJECTS,
            ACTION_DELETED,
            {"project_id": project_id, "project_name": project_name},
            codx_path=codx_path,
            project_id=project_id,
            source="session",
        )

