# Dynamically load and register all routers
def load_routers():
    """Load all discovered routers and register them with the FastAPI app."""
    routers = discover_routers()
    for router_config in routers:
        try:
            app.include_router(
                router_config['router'],
                prefix=router_config['prefix']
            )
            logger.info(f"Registered router from {router_config['module']}")
        except Exception as e:
            logger.error(f"Failed to register router {router_config['module']}: {e}")

load_routers()

APP_STOP_EVENT = asyncio.Event()

@app.on_event("startup")
async def startup_event():
    start_background_services(APP_STOP_EVENT)
    # Resume chat turns interrupted by a previous shutdown/crash. Runs in the
    # API process too (not only in the background one): the per-turn flock
    # guarantees a single owner across processes.
    try:
        from codx.junior.chat.turn_recovery import start_turn_recovery

        start_turn_recovery(stop_event=APP_STOP_EVENT)
    except Exception as ex:  # pragma: no cover - defensive
        logger.exception("Failed to start the chat turn recovery worker: %s", ex)
    # Harness watchdog: monitors the orchestration worker heartbeat from the
    # API process and restarts the background process when it stalls with
    # active runs. Never started inside the background process itself.
    try:
        from codx.junior.harness.watchdog import start_harness_watchdog

        start_harness_watchdog(stop_event=APP_STOP_EVENT)
    except Exception as ex:  # pragma: no cover - defensive
        logger.exception("Failed to start the harness watchdog: %s", ex)
    logger.info("FASTAPI startup")


@app.on_event("shutdown")
async def shutdown_event():
    logger.info("FASTAPI shutdown")
    APP_STOP_EVENT.set()
    try:
        from codx.junior.chat.turn_recovery import stop_turn_recovery

        stop_turn_recovery()
    except Exception as ex:  # pragma: no cover - defensive
        logger.exception("Failed to stop the chat turn recovery worker: %s", ex)
    try:
        from codx.junior.harness.watchdog import stop_harness_watchdog

        stop_harness_watchdog()
    except Exception as ex:  # pragma: no cover - defensive
        logger.exception("Failed to stop the harness watchdog: %s", ex)
    await stop_background_services()

